import React, { useEffect, useMemo, useState, useCallback } from 'react';
import {
  Card,
  Row,
  Col,
  Spinner,
  Button,
  Badge,
  ListGroup,
  Modal,
} from 'react-bootstrap';
import moment from 'moment';
import { useNavigate, useParams, useLocation } from 'react-router-dom';
import { FaArrowLeft, FaMapMarkerAlt, FaRoute, FaUser } from 'react-icons/fa';
import { GoogleMap, Marker, Polyline, useLoadScript } from '@react-google-maps/api';
import LiveMap from '../../components/liveMap/LiveMap';
import { NotificationContainer } from 'react-notifications';
import { usePageTitle, useRedux } from '../../hooks';
import { apiReturnCallBack, baseURL } from '../../api/ApiConfig';
import {
  getStaffIdGeolocationsRequest,
  resetGetStaffIdGeolocations,
  getBranchLocationEntryLogsRequest,
  resetGetBranchLocationEntryLogs,
  getPetrolAllowanceRequest,
  resetGetPetrolAllowance,
} from '../../redux/actions';

const VISIT_MAP_LIBS = ['places', 'geometry'];

function isValidCoordinate(latitude, longitude) {
  const lat = parseFloat(latitude);
  const lng = parseFloat(longitude);
  return !isNaN(lat) && !isNaN(lng) && Math.abs(lat) <= 90 && Math.abs(lng) <= 180 && !(lat === 0 && lng === 0);
}

const VisitorDetail = () => {
  const { staffId: urlStaffId, date: urlDate, entryLogId } = useParams();
  const navigate = useNavigate();
  const { dispatch, appSelector } = useRedux();

  const { pathname } = useLocation();
  const isFromVisitEntry = pathname.includes('/allowance/visit-entry');

  const [filterType, setFilterType] = useState('all');
  const [filterFromDate, setFilterFromDate] = useState('');
  const [filterToDate, setFilterToDate] = useState('');

  const [visitDetailsData, setVisitDetailsData] = useState(null);
  const [visitDetailsLoading, setVisitDetailsLoading] = useState(false);
  const [selectedFormDate, setSelectedFormDate] = useState(null);
  const [showFormModal, setShowFormModal] = useState(false);
  const [showMapModal, setShowMapModal] = useState(false);
  const [selectedVisitRoute, setSelectedVisitRoute] = useState(null);
  const [showAllRoutesModal, setShowAllRoutesModal] = useState(false);
  const [visitMapRef, setVisitMapRef] = useState(null);

  const { isLoaded: visitMapLoaded, loadError: visitMapError } = useLoadScript({
    googleMapsApiKey: 'AIzaSyD1Uvzt4qmx6O7DcUf0gH3DfrLssx_ARfc',
    libraries: VISIT_MAP_LIBS,
  });

  const [resolvedParams, setResolvedParams] = useState({
    staffId: urlStaffId || '',
    date: urlDate || '',
  });

  useEffect(() => {
    if (isFromVisitEntry && resolvedParams.staffId && resolvedParams.date) {
      setVisitDetailsLoading(true);
      apiReturnCallBack('GET', '/api/admin/visit-details', {
        user_id: resolvedParams.staffId,
        date: resolvedParams.date
      })
        .then(res => res.json())
        .then(data => {
          setVisitDetailsLoading(false);
          if (data && !data.error) {
            setVisitDetailsData(data.data);
          } else {
            setVisitDetailsData(null);
          }
        })
        .catch(err => {
          console.error(err);
          setVisitDetailsLoading(false);
          setVisitDetailsData(null);
        });
    }
  }, [isFromVisitEntry, resolvedParams.staffId, resolvedParams.date]);



  usePageTitle({
    title: 'Visitor Entry Detail',
    breadCrumbItems: isFromVisitEntry
      ? [
        {
          path: '/allowance/visit-entry',
          label: 'Visit Entry',
          active: false,
        },
        {
          path: `/allowance/visit-entry/${resolvedParams.staffId}/${resolvedParams.date}`,
          label: 'Visitor Detail',
          active: true,
        },
      ]
      : [
        {
          path: '/attendance/live-location-tracking',
          label: 'Live Location Tracking',
          active: false,
        },
        {
          path: `/attendance/live-location-tracking/visitor/${resolvedParams.staffId}/${resolvedParams.date}`,
          label: 'Visitor Detail',
          active: true,
        },
      ],
  });

  const {
    getStaffIdGeolocationsList,
    getStaffIdGeolocationsSuccess,
    isLoading,
    getBranchLocationEntryLogsList,
    getPetrolAllowanceList,
  } = appSelector((state) => ({
    getStaffIdGeolocationsList: state.staffGeolocationsReducer?.getStaffIdGeolocationsList,
    getStaffIdGeolocationsSuccess: state.staffGeolocationsReducer?.getStaffIdGeolocationsSuccess,
    isLoading: state.staffGeolocationsReducer?.isLoading || false,
    getBranchLocationEntryLogsList: state.staffGeolocationsReducer?.getBranchLocationEntryLogsList,
    getPetrolAllowanceList: state.petrolAllowanceReducer?.getPetrolAllowanceList,
  }));

  const getFormForDate = useCallback((date) => {
    if (!getPetrolAllowanceList || !Array.isArray(getPetrolAllowanceList)) return null;
    return getPetrolAllowanceList.find(pa =>
      pa.allowanceDate && moment(pa.allowanceDate).format('YYYY-MM-DD') === date && pa.isActive
    );
  }, [getPetrolAllowanceList]);

  const renderAttachment = (url) => {
    if (!url) return null;
    const attachUrl = url.startsWith('http') ? url : `${baseURL}${url}`;
    const isImage = /\.(jpg|jpeg|png|gif|webp|bmp|svg)$/i.test(url);
    return (
      <Row className="mb-3">
        <Col md={12}>
          <strong>Attachment:</strong>
          <div className="mt-2">
            {isImage ? (
              <img
                src={attachUrl}
                alt="Attachment"
                className="img-fluid rounded border"
                style={{ maxHeight: '200px' }}
                crossOrigin="anonymous"
                onError={(e) => { e.target.style.display = 'none'; e.target.nextElementSibling.style.display = 'block'; }}
              />
            ) : (
              <a href={attachUrl} target="_blank" rel="noreferrer" className="btn btn-outline-primary btn-sm">
                <i className="fe-download me-1"></i>View Attachment
              </a>
            )}
            <div className="text-danger font-size-12 mt-1" style={{ display: 'none' }}>Failed to load image</div>
          </div>
        </Col>
      </Row>
    );
  };

  const handleViewForm = useCallback((date, visitData) => {
    if (visitData) {
      setSelectedFormDate({
        type: 'visit',
        visit_out: visitData.visit_out,
        visit_in: visitData.visit_in,
        client_name: visitData.client_name,
        centre_no_name: visitData.centre_no_name,
        member_name: visitData.member_name,
        collection_amount: visitData.collection_amount,
        cell_no_name: visitData.cell_no_name,
        attachment: visitData.attachment,
        next_due_date: visitData.next_due_date,
        branch_visit: visitData.branch_visit,
        form_data: visitData.form_data,
        date: date,
      });
      setShowFormModal(true);
      return;
    }
    const form = getFormForDate(date);
    if (form) {
      setSelectedFormDate({ type: 'allowance', ...form });
      setShowFormModal(true);
    } else {
      alert('No form is submitted');
    }
  }, [getFormForDate]);

  const handleViewRouteModal = useCallback((visit) => {
    setSelectedVisitRoute(visit);
    setShowMapModal(true);
  }, []);

  const handleDateSelect = useCallback((date) => {
    if (!resolvedParams.staffId || date === resolvedParams.date) return;
    const newStaffId = resolvedParams.staffId;
    setResolvedParams({ staffId: newStaffId, date });
    dispatch(getStaffIdGeolocationsRequest({ staffId: newStaffId, date }));
  }, [dispatch, resolvedParams.staffId, resolvedParams.date]);

  // Effect 1: Handle mounting via entryLogId route
  useEffect(() => {
    if (entryLogId) {
      dispatch(resetGetBranchLocationEntryLogs());
      dispatch(getBranchLocationEntryLogsRequest({ entryLogId }));
    }
  }, [dispatch, entryLogId]);

  // Effect 2: Resolve staffId and date from loaded entry log
  useEffect(() => {
    if (entryLogId && getBranchLocationEntryLogsList && getBranchLocationEntryLogsList.length > 0) {
      const log = getBranchLocationEntryLogsList[0];
      if (String(log.entryLogId) === String(entryLogId)) {
        const sId = log.staffId;
        const dVal = moment(log.entryDate).format('YYYY-MM-DD');

        if (resolvedParams.staffId !== sId || resolvedParams.date !== dVal) {
          setResolvedParams({ staffId: sId, date: dVal });

          dispatch(resetGetStaffIdGeolocations());
          dispatch(getStaffIdGeolocationsRequest({ staffId: sId, date: dVal }));
        }
      }
    }
  }, [dispatch, entryLogId, getBranchLocationEntryLogsList, resolvedParams]);

  // Effect 3: Handle mounting via staffId / date route
  useEffect(() => {
    if (entryLogId) return;

    if (!urlStaffId || !urlDate) return;

    setResolvedParams({ staffId: urlStaffId, date: urlDate });

    dispatch(resetGetStaffIdGeolocations());
    dispatch(getStaffIdGeolocationsRequest({ staffId: urlStaffId, date: urlDate }));
  }, [dispatch, urlStaffId, urlDate, entryLogId]);

  // Effect 4: Fetch date-wise report data reactively when staffId or date filters change
  useEffect(() => {
    if (!resolvedParams.staffId) return;

    const logReq = { staffId: resolvedParams.staffId };
    const allowanceReq = { staffId: resolvedParams.staffId };

    if (filterType !== 'all') {
      logReq.fromDate = filterFromDate;
      logReq.toDate = filterToDate;
      allowanceReq.fromDate = filterFromDate;
      allowanceReq.toDate = filterToDate;
    }

    dispatch(resetGetBranchLocationEntryLogs());
    dispatch(getBranchLocationEntryLogsRequest(logReq));

    dispatch(resetGetPetrolAllowance());
    dispatch(getPetrolAllowanceRequest(allowanceReq));
  }, [dispatch, resolvedParams.staffId, filterType, filterFromDate, filterToDate]);

  const trackingData = useMemo(() => {
    if (!getStaffIdGeolocationsSuccess || !getStaffIdGeolocationsList) {
      return null;
    }

    if (getStaffIdGeolocationsList.records) {
      return getStaffIdGeolocationsList;
    }

    return { records: getStaffIdGeolocationsList };
  }, [getStaffIdGeolocationsSuccess, getStaffIdGeolocationsList]);

  const records = trackingData?.records || {};
  const geoLocations = records.geoLocation || [];
  const totalDistance = records.totalDistance || 0;

  // Now define visitRouteData AFTER records is available
  const visitRouteData = useMemo(() => {
  if (!visitDetailsData?.visits) return { markers: [], paths: [] };

  const markers = [];
  const paths = [];

  visitDetailsData.visits.forEach((visit, idx) => {

    // console.log("========== VISIT ==========");
    // console.log("Visit Index:", idx);

    // console.log("Visit In:", visit.visit_in_location);
    // console.log("Visit Out:", visit.visit_out_location);

    // console.log("ROUTE POINTS:", visit.route_points);

    if (visit.route_points) {
      visit.route_points.forEach((p, i) => {
        console.log(`Point ${i}:`, p.lat, p.lng);
      });
    }

    if (visit.visit_in_location) {
      markers.push({
        ...visit.visit_in_location,
        label: `V${idx + 1} In`,
        type: 'in',
        visitIdx: idx
      });
    }

    if (visit.visit_out_location) {
      markers.push({
        ...visit.visit_out_location,
        label: `V${idx + 1} Out`,
        type: 'out',
        visitIdx: idx
      });
    }

    let path = [];

    if (visit.route_points && visit.route_points.length > 0) {
    const rawPoints = visit.route_points
      .map(p => ({
        lat: parseFloat(p.lat),
        lng: parseFloat(p.lng)
      }))
      .filter(p => !isNaN(p.lat) && !isNaN(p.lng));

    // Detect repeating base point (the noisy hub that breaks the route)
    const freq = {};
    rawPoints.forEach(p => {
      const key = `${p.lat.toFixed(6)},${p.lng.toFixed(6)}`;
      freq[key] = (freq[key] || 0) + 1;
    });

    let baseKey = null;
    let max = 0;

    for (let key in freq) {
      if (freq[key] > max) {
        max = freq[key];
        baseKey = key;
      }
    }

    console.log("BASE POINT DETECTED:", baseKey);

    // Remove ALL occurrences of the base point - it's a noisy hub
    // that zigzags the route and makes it look like a filled polygon
    const filtered = rawPoints.filter(p => {
      const key = `${p.lat.toFixed(6)},${p.lng.toFixed(6)}`;
      return key !== baseKey;
    });

    // Remove consecutive duplicates
    path = filtered.filter((p, i) =>
      i === 0 ||
      p.lat !== filtered[i - 1].lat ||
      p.lng !== filtered[i - 1].lng
    );
    }

    if (path.length >= 2) {
    paths.push(path);
    }
  });return { markers, paths };
}, [visitDetailsData]);
  

  const visitMapCenter = useMemo(() => {
    if (visitRouteData.markers.length > 0) return visitRouteData.markers[0];
    return { lat: 11.341, lng: 77.7172 };
  }, [visitRouteData.markers]);

  const fitVisitBounds = useCallback(() => {
    if (visitMapRef && visitRouteData.markers.length > 0) {
      const bounds = new window.google.maps.LatLngBounds();
      visitRouteData.markers.forEach(m => bounds.extend(m));
      visitMapRef.fitBounds(bounds);
    }
  }, [visitMapRef, visitRouteData.markers]);

  const visitRoutePath = useMemo(() => {
    if (!selectedVisitRoute?.visit_in_location || !selectedVisitRoute?.visit_out_location) return [];
    const inLoc = selectedVisitRoute.visit_in_location;
    const outLoc = selectedVisitRoute.visit_out_location;

    let points = [];
    if (selectedVisitRoute.route_points && selectedVisitRoute.route_points.length > 0) {
      points = selectedVisitRoute.route_points.map(p => ({
        lat: typeof p.lat === 'string' ? parseFloat(p.lat) : p.lat,
        lng: typeof p.lng === 'string' ? parseFloat(p.lng) : p.lng
      })).filter(p => !isNaN(p.lat) && !isNaN(p.lng));

      // Remove noisy repeating base point that zigzags the route
      const freq = {};
      points.forEach(p => {
        const key = `${p.lat.toFixed(6)},${p.lng.toFixed(6)}`;
        freq[key] = (freq[key] || 0) + 1;
      });
      let baseKey = null, max = 0;
      for (let key in freq) {
        if (freq[key] > max) { max = freq[key]; baseKey = key; }
      }
      if (baseKey) {
        points = points.filter(p => `${p.lat.toFixed(6)},${p.lng.toFixed(6)}` !== baseKey);
      }
    }

    const haversine = (a, b) => { const R=6371000, dLat=(b.lat-a.lat)*Math.PI/180, dLng=(b.lng-a.lng)*Math.PI/180, sDLat=Math.sin(dLat/2), sDLng=Math.sin(dLng/2), aa=sDLat*sDLat+Math.cos(a.lat*Math.PI/180)*Math.cos(b.lat*Math.PI/180)*sDLng*sDLng; return R*2*Math.atan2(Math.sqrt(aa),Math.sqrt(1-aa)); };

    const path = [inLoc];
    for (const p of points) {
      if (haversine(path[path.length - 1], p) > 3) path.push(p);
    }
    if (points.length > 0 && haversine(path[path.length - 1], outLoc) > 3) path.push(outLoc);
    if (path.length < 2) return [inLoc, outLoc];
    return path;
  }, [selectedVisitRoute]);

  const originPoint = useMemo(() => {
    const locations = records.geoLocation || [];
    return locations.find((point) => isValidCoordinate(point.latitude, point.longitude)) || null;
  }, [records.geoLocation]);

  const handleOriginClick = () => {
    if (!originPoint) return;
    const lat = parseFloat(originPoint.latitude);
    const lng = parseFloat(originPoint.longitude);
    window.open(`https://www.google.com/maps?q=${lat},${lng}`, '_blank');
  };

  // Compile date-wise report for the employee
  const dateWiseReport = useMemo(() => {
    const logsList = Array.isArray(getBranchLocationEntryLogsList) ? getBranchLocationEntryLogsList : (getBranchLocationEntryLogsList?.data || []);
    if (!logsList || logsList.length === 0) {
      return [];
    }

    const grouped = {};
    logsList.forEach((log) => {
      // Ignore if it's the single log entry query payload
      if (entryLogId && String(log.entryLogId) === String(entryLogId) && !log.staffFullName && !log.employeeName) {
        return;
      }

      const entryDate = moment(log.entryDate).format('YYYY-MM-DD');
      if (!grouped[entryDate]) {
        grouped[entryDate] = {
          date: entryDate,
          totalKm: Number(log.totalKm) || 0,
          locations: [],
          entryLogId: log.entryLogId,
        };
      } else {
        grouped[entryDate].totalKm += Number(log.totalKm) || 0;
      }
      if (log.officeName && !grouped[entryDate].locations.includes(log.officeName)) {
        grouped[entryDate].locations.push(log.officeName);
      } else if (log.registeredBranchName && !grouped[entryDate].locations.includes(log.registeredBranchName)) {
        grouped[entryDate].locations.push(log.registeredBranchName);
      }
    });

    const petrolDates = new Set();
    if (getPetrolAllowanceList && Array.isArray(getPetrolAllowanceList)) {
      getPetrolAllowanceList.forEach((pa) => {
        if (pa.allowanceDate && pa.isActive) {
          petrolDates.add(moment(pa.allowanceDate).format('YYYY-MM-DD'));
        }
      });
    }

    return Object.values(grouped).map((row) => {
      const isSubmitted = petrolDates.has(row.date);
      return {
        ...row,
        formStatus: isSubmitted ? 'Submitted' : 'Not Submitted',
        locationsList: row.locations.length > 0 ? row.locations.join(', ') : 'N/A',
      };
    }).sort((a, b) => new Date(b.date) - new Date(a.date));
  }, [getBranchLocationEntryLogsList, getPetrolAllowanceList, entryLogId]);

  // Extract Employee Name and Code from records, or fallback to branch logs
  const logsList = Array.isArray(getBranchLocationEntryLogsList) ? getBranchLocationEntryLogsList : (getBranchLocationEntryLogsList?.data || []);
  const employeeName = records.empName || 
    (logsList.find(l => l.staffFullName || l.employeeName)?.staffFullName) || 
    (logsList.find(l => l.staffFullName || l.employeeName)?.employeeName) || 
    'Employee';

  const employeeCode = records.empCode || 
    (logsList.find(l => l.staffCode)?.staffCode) || 
    resolvedParams.staffId;

  const filterPeriodTotalKm = useMemo(() => {
    return dateWiseReport.reduce((sum, row) => sum + (Number(row.totalKm) || 0), 0);
  }, [dateWiseReport]);

  return (
    <React.Fragment>
      <NotificationContainer />
      <div className="mb-3">
        <Button
          variant="outline-secondary"
          onClick={() => navigate(-1)}
        >
          <FaArrowLeft className="me-2" />
          Back
        </Button>
      </div>

      {/* Employee Info & Total Distance Card */}
      {resolvedParams.staffId && (
        <Card className="mb-3 border-0 shadow-sm bg-white">
          <Card.Body className="p-3">
            <Row className="align-items-center">
              <Col md={6} xs={12} className="d-flex align-items-center gap-3">
                <div
                  className="rounded-circle d-flex align-items-center justify-content-center text-primary"
                  style={{ width: '48px', height: '48px', backgroundColor: '#eef2f7' }}
                >
                  <FaUser size={20} />
                </div>
                <div>
                  <h5 className="mb-0 text-dark fw-bold">{employeeName}</h5>
                  <span className="text-muted font-size-13">Employee Code: <span className="fw-semibold text-secondary">{employeeCode}</span></span>
                </div>
              </Col>
              <Col md={6} xs={12} className="text-md-end mt-2 mt-md-0">
                <div>
                  <span className="text-secondary font-size-13 fw-semibold">Total Traveled Distance</span>
                  <h3 className="mb-0 text-primary fw-bold mt-1">
                    <FaRoute className="me-2 text-info" />
                    {filterPeriodTotalKm.toFixed(2)} km
                  </h3>
                </div>
              </Col>
            </Row>
          </Card.Body>
        </Card>
      )}

      {isFromVisitEntry && (
        <Card className="mb-3 border-0 shadow-sm">
          <Card.Header className="bg-light py-3">
            <h5 className="mb-0 fw-bold text-dark">Visit Details ({moment(resolvedParams.date).format('DD-MMM-YYYY')})</h5>
          </Card.Header>
          <Card.Body>
            {visitDetailsLoading ? (
              <div className="text-center py-4">
                <Spinner animation="border" variant="primary" />
                <p className="mt-2 text-secondary">Loading visit details...</p>
              </div>
            ) : visitDetailsData ? (
              <>
                {/* TOP SECTION: Summary Card */}
                <Row className="g-3 mb-4">
                  <Col md={6}>
                    <Card className="bg-info-lighten border-info border text-info shadow-none">
                      <Card.Body className="p-3 text-center">
                        <div className="text-uppercase font-size-12 fw-bold mb-1">Visit Count</div>
                        <h3 className="mb-0 fw-bold">{visitDetailsData.summary?.total_visits || 0}</h3>
                      </Card.Body>
                    </Card>
                  </Col>
                  <Col md={6}>
                    <Card className="bg-success-lighten border-success border text-success shadow-none">
                      <Card.Body className="p-3 text-center">
                        <div className="text-uppercase font-size-12 fw-bold mb-1">Total Distance</div>
                        <h3 className="mb-0 fw-bold">{Number(visitDetailsData.summary?.total_km || 0).toFixed(2)} KM</h3>
                      </Card.Body>
                    </Card>
                  </Col>
                </Row>

                {/* LIST SECTION: Visit Cards */}
                <div className="visit-cards-container">
                  {visitDetailsData.visits && visitDetailsData.visits.length > 0 ? (
                    visitDetailsData.visits.map((visit, idx) => (
                      <Card key={idx} className="mb-3 border border-secondary-10 shadow-none bg-light-lighten">
                        <Card.Body className="p-3">
                          <Row className="align-items-center">
                            <Col md={8} xs={12}>
                              <h5 className="mb-2 text-dark fw-bold">{visit.client_name}</h5>
                              <div className="d-flex gap-3 text-secondary font-size-13 mb-1">
                                <div><strong>Visit In:</strong> {visit.visit_in}</div>
                                <div><strong>Visit Out:</strong> {visit.visit_out}</div>
                              </div>
                              <div className="text-muted font-size-12">
                                <strong>Duration:</strong> {visit.duration}
                              </div>
                            </Col>
                            <Col md={4} xs={12} className="text-md-end mt-2 mt-md-0">
                              <h4 className="text-primary fw-bold mb-2">{Number(visit.km).toFixed(2)} KM</h4>
                              <div className="d-flex justify-content-md-end gap-2">
                                <Button
                                  variant="outline-secondary"
                                  size="sm"
                                  title="View Document"
                                  onClick={() => handleViewForm(moment(resolvedParams.date).format('YYYY-MM-DD'), visit)}
                                >
                                  <i className="fe-file-text"></i>
                                </Button>
                                {(visit.visit_out_location || visit.visit_in_location) && (
                                  <Button
                                    variant="outline-danger"
                                    size="sm"
                                    title="View Route"
                                    onClick={() => handleViewRouteModal(visit)}
                                  >
                                    <i className="fe-map-pin"></i>
                                  </Button>
                                )}
                              </div>
                            </Col>
                          </Row>
                        </Card.Body>
                      </Card>
                    ))
                  ) : (
                    <div className="text-center py-4 bg-white border border-dashed rounded">
                      <span className="text-muted">No visits recorded on this date.</span>
                    </div>
                  )}
                </div>

                {/* Visit Route Map Preview */}
                {visitRouteData.markers.length > 0 && (visitMapError ? (
                  <div className="text-center py-3 text-danger">Error loading map</div>
                ) : !visitMapLoaded ? (
                  <div className="text-center py-3">
                    <Spinner animation="border" variant="primary" size="sm" />
                    <span className="ms-2 text-muted">Loading map...</span>
                  </div>
                ) : (
                  <Card className="border shadow-none mt-3" style={{ cursor: 'pointer' }} onClick={() => setShowAllRoutesModal(true)}>
                    <Card.Header className="bg-light py-2">
                      <span className="fw-semibold text-dark">
                        <FaRoute className="me-2 text-primary" />
                        Visit Route Map (All visits overview) <small className="text-muted">— Click to expand</small>
                      </span>
                    </Card.Header>
                    <Card.Body className="p-2" style={{ height: '200px' }}>
                      <GoogleMap
                        mapContainerStyle={{ width: '100%', height: '100%' }}
                        zoom={14}
                        center={visitMapCenter}
                        options={{
                          streetViewControl: false,
                          mapTypeControl: false,
                          fullscreenControl: false,
                          zoomControl: false,
                          scrollwheel: false,
                          draggable: false,
                          disableDoubleClickZoom: true,
                          styles: [{ featureType: 'poi', elementType: 'labels', stylers: [{ visibility: 'off' }] }],
                        }}
                        onLoad={(map) => { setVisitMapRef(map); setTimeout(() => fitVisitBounds(), 300); }}
                      >
                        {visitRouteData.paths.map((path, idx) => (
                          <Polyline
                            key={`path-${idx}`}
                            path={path}
                            options={{
                              strokeColor: idx % 2 === 0 ? '#F97316' : '#8B5CF6',
                              strokeOpacity: 0.8,
                              strokeWeight: 3,
                              geodesic: true,
                              icons: [{
                                icon: {
                                  path: window.google.maps.SymbolPath.FORWARD_CLOSED_ARROW,
                                  fillColor: '#FFFFFF',
                                  fillOpacity: 1,
                                  strokeColor: '#F97316',
                                  strokeWeight: 2,
                                  scale: 1.5,
                                },
                                offset: '100%',
                                repeat: '120px',
                              }],
                            }}
                          />
                        ))}
                        {visitRouteData.markers.map((m, idx) => (
                          <Marker
                            key={`vm-${idx}`}
                            position={{ lat: m.lat, lng: m.lng }}
                            icon={{
                              url: m.type === 'in'
                                ? 'http://maps.google.com/mapfiles/ms/icons/green-dot.png'
                                : 'http://maps.google.com/mapfiles/ms/icons/red-dot.png',
                              scaledSize: new window.google.maps.Size(32, 32),
                            }}
                            label={{
                              text: m.label,
                              color: '#fff',
                              fontSize: '10px',
                              fontWeight: 'bold',
                            }}
                          />
                        ))}
                      </GoogleMap>
                    </Card.Body>
                  </Card>
                ))}
              </>
            ) : (
              <div className="text-center py-4 bg-white border border-dashed rounded">
                <span className="text-muted">Failed to load visit details.</span>
              </div>
            )}
          </Card.Body>
        </Card>
      )}

      {/* Only display map coordinates and paths if NOT accessed from Visit Entry list */}
      {!isFromVisitEntry && (
        geoLocations.length > 0 ? (
          <Card className="mb-3 border-0 shadow-sm">
            <Card.Header className="bg-primary text-white py-3">
              <div className="d-flex justify-content-between align-items-center">
                <h5 className="mb-0 fw-bold">
                  <FaUser className="me-2" />
                  {employeeName} ({employeeCode})
                </h5>
                <Badge bg="light" className="text-primary font-size-13 py-1.5 px-2">
                  Visit date: {moment(resolvedParams.date).format('DD-MMM-YYYY')}
                </Badge>
              </div>
            </Card.Header>
            <Card.Body>
              <Row>
                <Col md={4}>
                  <ListGroup variant="flush" className="border rounded">
                    <ListGroup.Item className="d-flex justify-content-between align-items-center py-3">
                      <span className="fw-medium text-secondary">Total Distance</span>
                      <Badge bg="info" className="px-2 py-1.5 font-size-12">
                        <FaRoute className="me-1" />
                        {Number(totalDistance).toFixed(2)} km
                      </Badge>
                    </ListGroup.Item>
                    <ListGroup.Item className="py-3">
                      <div className="fw-medium text-secondary mb-2">From Location</div>
                      {originPoint ? (
                        <Button
                          variant="link"
                          className="p-0 text-start text-primary fw-semibold"
                          onClick={handleOriginClick}
                        >
                          <FaMapMarkerAlt className="me-1 text-danger" />
                          {originPoint.coordinatesPoints ||
                            `${originPoint.latitude}, ${originPoint.longitude}`}
                        </Button>
                      ) : (
                        <span className="text-muted">No valid origin coordinate</span>
                      )}
                    </ListGroup.Item>
                    <ListGroup.Item className="d-flex justify-content-between align-items-center py-3">
                      <span className="fw-medium text-secondary">GPS Points</span>
                      <Badge bg="secondary" className="px-2 py-1.5 font-size-12">{geoLocations.length}</Badge>
                    </ListGroup.Item>
                  </ListGroup>
                </Col>
                <Col md={8}>
                  <Card className="border shadow-none">
                    <Card.Header className="bg-light py-2.5">
                      <span className="fw-semibold text-dark">
                        <FaRoute className="me-2 text-primary" />
                        Travel Path Map
                      </span>
                    </Card.Header>
                    <Card.Body style={{ minHeight: '500px' }} className="p-2">
                      {isLoading ? (
                        <div className="text-center py-5">
                          <Spinner animation="border" variant="primary" />
                          <p className="mt-2 text-secondary">Loading travel path...</p>
                        </div>
                      ) : (
                        <div style={{ height: '500px' }}>
                          <LiveMap data={trackingData} />
                        </div>
                      )}
                    </Card.Body>
                  </Card>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        ) : (
          <Card className="mb-3 border-0 shadow-sm">
            <Card.Header className="bg-primary text-white py-3">
              <div className="d-flex justify-content-between align-items-center">
                <h5 className="mb-0 fw-bold">
                  <FaUser className="me-2" />
                  {employeeName} ({employeeCode})
                </h5>
                <Badge bg="light" className="text-primary font-size-13 py-1.5 px-2">
                  Visit date: {moment(resolvedParams.date).format('DD-MMM-YYYY')}
                </Badge>
              </div>
            </Card.Header>
            <Card.Body>
              <div className="p-3 bg-light rounded border mb-2">
                <h6 className="text-dark fw-bold mb-3">Visit Details for {moment(resolvedParams.date).format('DD-MMM-YYYY')}</h6>
                <Row className="g-3">
                  <Col md={3}>
                    <div className="text-secondary font-size-13">KM Traveled</div>
                    <div className="fw-bold font-size-16 mt-1 text-dark">
                      {(() => {
                        const matchingRow = dateWiseReport.find(r => r.date === moment(resolvedParams.date).format('YYYY-MM-DD'));
                        return matchingRow ? Number(matchingRow.totalKm).toFixed(2) : Number(totalDistance).toFixed(2);
                      })()} km
                    </div>
                  </Col>
                  <Col md={3}>
                    <div className="text-secondary font-size-13">Form Status</div>
                    <div className="mt-1">
                      {(() => {
                        const matchingRow = dateWiseReport.find(r => r.date === moment(resolvedParams.date).format('YYYY-MM-DD'));
                        const status = matchingRow ? matchingRow.formStatus : 'Not Submitted';
                        return status === 'Submitted' ? (
                          <Badge
                            bg="success"
                            className="px-2.5 py-1.5 font-size-12 cursor-pointer"
                            style={{ cursor: 'pointer' }}
                            onClick={() => handleViewForm(moment(resolvedParams.date).format('YYYY-MM-DD'))}
                            title="View form details"
                          >
                            Submitted
                          </Badge>
                        ) : (
                          <Badge bg="danger" className="px-2.5 py-1.5 font-size-12">Not Submitted</Badge>
                        );
                      })()}
                    </div>
                  </Col>
                  <Col md={6}>
                    <div className="text-secondary font-size-13">Visited Location</div>
                    <div className="fw-bold font-size-16 mt-1 text-dark">
                      {(() => {
                        const matchingRow = dateWiseReport.find(r => r.date === moment(resolvedParams.date).format('YYYY-MM-DD'));
                        return matchingRow ? matchingRow.locationsList : 'N/A';
                      })()}
                    </div>
                  </Col>
                </Row>
              </div>
              <div className="text-center text-muted py-4 bg-white border border-dashed rounded mt-3">
                <span className="font-size-14">No live GPS tracking route available for this date.</span>
              </div>
            </Card.Body>
          </Card>
        )
      )}

      {/* Date-wise report */}
      <Card className="mt-4 border-0 shadow-sm">
        <Card.Header className="bg-white border-bottom py-3">
          <div className="d-flex justify-content-between align-items-center flex-wrap gap-2">
            <h5 className="mb-0 text-dark fw-bold">
              <FaRoute className="me-2 text-primary" />
              Date-wise Visited Report
            </h5>
            <Badge bg="secondary" className="px-2.5 py-1.5">
              {dateWiseReport.length} Days Tracked
            </Badge>
          </div>
          <div className="d-flex align-items-center gap-3 flex-wrap mt-2 pt-2 border-top">
            <span className="fw-bold text-dark font-size-14">Filter:</span>
            <div className="btn-group" role="group">
              <Button
                variant={filterType === 'all' ? 'primary' : 'outline-primary'}
                size="sm"
                onClick={() => setFilterType('all')}
              >
                All
              </Button>
              <Button
                variant={filterType === 'today' ? 'primary' : 'outline-primary'}
                size="sm"
                onClick={() => {
                  setFilterType('today');
                  setFilterFromDate(moment().format('YYYY-MM-DD'));
                  setFilterToDate(moment().format('YYYY-MM-DD'));
                }}
              >
                Today
              </Button>
            </div>
            <div style={{ minWidth: '130px' }}>
              <label className="form-label mb-0 text-secondary font-size-12">From</label>
              <input
                type="date"
                className="form-control form-control-sm"
                value={filterFromDate}
                max={filterToDate || moment().format("YYYY-MM-DD")}
                onChange={(e) => {
                  setFilterFromDate(e.target.value);
                  setFilterType('custom');
                }}
              />
            </div>
            <div style={{ minWidth: '130px' }}>
              <label className="form-label mb-0 text-secondary font-size-12">To</label>
              <input
                type="date"
                className="form-control form-control-sm"
                value={filterToDate}
                min={filterFromDate}
                max={moment().format("YYYY-MM-DD")}
                onChange={(e) => {
                  setFilterToDate(e.target.value);
                  setFilterType('custom');
                }}
              />
            </div>
          </div>
        </Card.Header>
        <Card.Body className="p-0">
          <div className="table-responsive">
            <table className="table table-hover align-middle mb-0">
              <thead className="table-light">
                <tr>
                  <th className="ps-4 py-3 text-secondary text-uppercase font-size-12">Date</th>
                  <th className="py-3 text-secondary text-uppercase font-size-12">Total KM</th>
                  <th className="py-3 text-secondary text-uppercase font-size-12">Location (Visited Branch)</th>
                  <th className="py-3 text-secondary text-uppercase font-size-12">Form Status</th>
                  <th className="pe-4 py-3 text-end text-secondary text-uppercase font-size-12">Action</th>
                </tr>
              </thead>
              <tbody>
                {dateWiseReport.length > 0 ? (
                  dateWiseReport.map((row, index) => {
                    const isActiveDate = row.date === moment(resolvedParams.date).format('YYYY-MM-DD');
                    const isToday = row.date === moment().format('YYYY-MM-DD');
                    return (
                      <tr
                        key={index}
                        className={`${isActiveDate ? 'table-primary font-weight-semibold' : ''} cursor-pointer`}
                        onClick={() => handleDateSelect(row.date)}
                        style={{ cursor: 'pointer' }}
                      >
                        <td className="ps-4 fw-medium text-dark">
                          {moment(row.date).format('DD-MMM-YYYY')}
                          {isActiveDate && (
                            <Badge bg="primary" className="ms-2" style={{ fontSize: '10px' }}>
                              Active Path
                            </Badge>
                          )}
                        </td>
                        <td className="fw-medium">{Number(row.totalKm).toFixed(2)} km</td>
                        <td className="text-muted">{row.locationsList}</td>
                        <td>
                          {row.formStatus === 'Submitted' ? (
                            <Badge
                              bg="success"
                              className="px-2 py-1 cursor-pointer"
                              style={{ cursor: 'pointer' }}
                              onClick={(e) => { e.stopPropagation(); handleViewForm(row.date); }}
                              title="View form details"
                            >
                              Submitted
                            </Badge>
                          ) : (
                            <Badge bg="danger" className="px-2 py-1">Not Submitted</Badge>
                          )}
                        </td>
                        <td className="pe-4 text-end">
                          <Button
                            variant={isToday ? 'success' : 'outline-primary'}
                            size="sm"
                            onClick={(e) => {
                              e.stopPropagation();
                              handleDateSelect(row.date);
                            }}
                          >
                            <FaMapMarkerAlt className="me-1" />
                            View Path
                          </Button>
                        </td>
                      </tr>
                    );
                  })
                ) : (
                  <tr>
                    <td colSpan="5" className="text-center text-muted py-5">
                      No visitor entry logs found for this employee.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </Card.Body>
      </Card>

      {/* Route Map Modal - per visit */}
      <Modal show={showMapModal} onHide={() => setShowMapModal(false)} centered size="xl" fullscreen="lg">
        <Modal.Header closeButton>
          <Modal.Title>
            <FaRoute className="me-2 text-primary" />
            Visit Route - {selectedVisitRoute?.client_name || 'Visit'} ({moment(resolvedParams.date).format('DD-MMM-YYYY')})
          </Modal.Title>
        </Modal.Header>
        <Modal.Body style={{ height: '70vh', padding: 0 }}>
          {selectedVisitRoute && selectedVisitRoute.visit_in_location && selectedVisitRoute.visit_out_location ? (visitMapError ? (
            <div className="d-flex align-items-center justify-content-center h-100 text-danger">Error loading map</div>
          ) : !visitMapLoaded ? (
            <div className="d-flex align-items-center justify-content-center h-100">
              <Spinner animation="border" variant="primary" size="sm" />
              <span className="ms-2 text-muted">Loading map...</span>
            </div>
          ) : (
            <GoogleMap
              mapContainerStyle={{ width: '100%', height: '100%' }}
              center={selectedVisitRoute.visit_in_location}
              zoom={14}
              options={{
                streetViewControl: true,
                mapTypeControl: true,
                fullscreenControl: true,
                zoomControl: true,
                styles: [{ featureType: 'poi', elementType: 'labels', stylers: [{ visibility: 'off' }] }],
              }}
              onLoad={(map) => {
                const bounds = new window.google.maps.LatLngBounds();
                bounds.extend(selectedVisitRoute.visit_in_location);
                bounds.extend(selectedVisitRoute.visit_out_location);
                visitRoutePath.forEach(p => bounds.extend(p));
                map.fitBounds(bounds, { top: 50, bottom: 50, left: 50, right: 50 });
              }}
            >
              <Marker
                position={selectedVisitRoute.visit_in_location}
                icon={{
                  url: 'http://maps.google.com/mapfiles/ms/icons/green-dot.png',
                  scaledSize: new window.google.maps.Size(40, 40),
                }}
                label={{
                  text: 'In',
                  color: '#fff',
                  fontSize: '11px',
                  fontWeight: 'bold',
                }}
              />
              <Marker
                position={selectedVisitRoute.visit_out_location}
                icon={{
                  url: 'http://maps.google.com/mapfiles/ms/icons/red-dot.png',
                  scaledSize: new window.google.maps.Size(40, 40),
                }}
                label={{
                  text: 'Out',
                  color: '#fff',
                  fontSize: '11px',
                  fontWeight: 'bold',
                }}
              />
              {visitRoutePath.length > 0 && (
                <Polyline
                  path={visitRoutePath}
                  options={{
                    strokeColor: '#F97316',
                    strokeOpacity: 0.8,
                    strokeWeight: 4,
                    geodesic: true,
                    icons: [{
                      icon: {
                        path: window.google.maps.SymbolPath.FORWARD_CLOSED_ARROW,
                        fillColor: '#FFFFFF',
                        fillOpacity: 1,
                        strokeColor: '#F97316',
                        strokeWeight: 2,
                        scale: 1.5,
                      },
                      offset: '100%',
                      repeat: '120px',
                    }],
                  }}
                />
              )}
            </GoogleMap>
          )) : (
            <div className="d-flex align-items-center justify-content-center h-100 text-muted">
              No location data available for this visit.
            </div>
          )}
        </Modal.Body>
        <Modal.Footer>
          <div className="d-flex align-items-center me-auto font-size-13 text-secondary">
            <span className="badge bg-success me-2">Green: Visit In</span>
            <span className="badge bg-danger me-2">Red: Visit Out</span>
            <span>Distance: {Number(selectedVisitRoute?.km || 0).toFixed(2)} KM</span>
          </div>
          <Button variant="secondary" onClick={() => setShowMapModal(false)}>Close</Button>
        </Modal.Footer>
      </Modal>

      {/* All Routes Overview Modal */}
      <Modal show={showAllRoutesModal} onHide={() => setShowAllRoutesModal(false)} centered size="xl" fullscreen="lg">
        <Modal.Header closeButton>
          <Modal.Title>
            <FaRoute className="me-2 text-primary" />
            Visit Route Map (All visits overview) — {moment(resolvedParams.date).format('DD-MMM-YYYY')}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body style={{ height: '70vh', padding: 0 }}>
          {visitRouteData.markers.length > 0 ? (visitMapError ? (
            <div className="d-flex align-items-center justify-content-center h-100 text-danger">Error loading map</div>
          ) : !visitMapLoaded ? (
            <div className="d-flex align-items-center justify-content-center h-100">
              <Spinner animation="border" variant="primary" size="sm" />
              <span className="ms-2 text-muted">Loading map...</span>
            </div>
          ) : (
            <GoogleMap
              mapContainerStyle={{ width: '100%', height: '100%' }}
              center={visitMapCenter}
              zoom={14}
              options={{
                streetViewControl: true,
                mapTypeControl: true,
                fullscreenControl: true,
                zoomControl: true,
                styles: [{ featureType: 'poi', elementType: 'labels', stylers: [{ visibility: 'off' }] }],
              }}
              onLoad={(map) => {
                const bounds = new window.google.maps.LatLngBounds();
                visitRouteData.markers.forEach(m => bounds.extend({ lat: m.lat, lng: m.lng }));
                visitRouteData.paths.forEach(p => { if (p[0]) bounds.extend(p[0]); if (p[1]) bounds.extend(p[1]); });
                map.fitBounds(bounds);
              }}
            >
              {visitRouteData.paths.map((path, idx) => (
                <Polyline
                  key={`modal-path-${idx}`}
                  path={path}
                  options={{
                    strokeColor: idx % 2 === 0 ? '#F97316' : '#8B5CF6',
                    strokeOpacity: 0.8,
                    strokeWeight: 3,
                    geodesic: true,
                    icons: [{
                      icon: {
                        path: window.google.maps.SymbolPath.FORWARD_CLOSED_ARROW,
                        fillColor: '#FFFFFF',
                        fillOpacity: 1,
                        strokeColor: '#F97316',
                        strokeWeight: 2,
                        scale: 1.5,
                      },
                      offset: '100%',
                      repeat: '120px',
                    }],
                  }}
                />
              ))}
              {visitRouteData.markers.map((m, idx) => (
                <Marker
                  key={`modal-vm-${idx}`}
                  position={{ lat: m.lat, lng: m.lng }}
                  icon={{
                    url: m.type === 'in'
                      ? 'http://maps.google.com/mapfiles/ms/icons/green-dot.png'
                      : 'http://maps.google.com/mapfiles/ms/icons/red-dot.png',
                    scaledSize: window.google.maps.Size ? new window.google.maps.Size(36, 36) : null,
                  }}
                  label={{
                    text: m.label,
                    color: '#fff',
                    fontSize: '10px',
                    fontWeight: 'bold',
                  }}
                />
              ))}
            </GoogleMap>
          )) : (
            <div className="d-flex align-items-center justify-content-center h-100 text-muted">
              No location data available for this date.
            </div>
          )}
        </Modal.Body>
        <Modal.Footer>
          <div className="d-flex align-items-center me-auto font-size-13 text-secondary">
            <span className="badge bg-success me-2">Green: Visit In</span>
            <span className="badge bg-danger me-2">Red: Visit Out</span>
            <span>{visitRouteData.markers.length} Locations</span>
          </div>
          <Button variant="secondary" onClick={() => setShowAllRoutesModal(false)}>Close</Button>
        </Modal.Footer>
      </Modal>

      {/* Form Details Modal */}
      <Modal show={showFormModal} onHide={() => setShowFormModal(false)} centered size="lg">
        <Modal.Header closeButton>
          <Modal.Title>Visit Entry Form Details</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedFormDate ? (
            selectedFormDate.type === 'visit' ? (
              (() => {
                const cat = (selectedFormDate.centre_no_name || '').trim();
                const categoryFormTypes = ['Collection', 'Delivery', 'Follow-up Visit', 'New Account Opening', 'Complaint Resolution'];
                const isCategory = categoryFormTypes.includes(cat);

                const fields = [];
                fields.push({ label: 'Client Name', value: selectedFormDate.client_name });
                fields.push({ label: 'Date', value: moment(selectedFormDate.date).format('DD-MMM-YYYY') });
                fields.push({ label: 'Visit Category', value: cat || selectedFormDate.centre_no_name });
                if (selectedFormDate.member_name) fields.push({ label: 'Contact Person', value: selectedFormDate.member_name });
                if (selectedFormDate.cell_no_name) fields.push({ label: 'Mobile Number', value: selectedFormDate.cell_no_name });

                if (isCategory) {
                  const fd = selectedFormDate.form_data || {};
                  switch (cat) {
                    case 'Collection':
                      const colAmt = fd.collectionAmount || selectedFormDate.collection_amount;
                      const payMode = fd.paymentMode || selectedFormDate.branch_visit;
                      const recNo = fd.receiptNo;
                      if (colAmt) fields.push({ label: 'Collection Amount', value: colAmt });
                      if (payMode) fields.push({ label: 'Payment Mode', value: payMode });
                      if (recNo) fields.push({ label: 'Receipt No', value: recNo });
                      break;
                    case 'Delivery':
                      const qty = fd.quantity || selectedFormDate.collection_amount;
                      const rxBy = fd.receivedBy || selectedFormDate.branch_visit;
                      if (qty) fields.push({ label: 'Quantity', value: qty });
                      if (rxBy) fields.push({ label: 'Received By', value: rxBy });
                      break;
                    case 'Follow-up Visit':
                      const discTopics = fd.discussionTopics || selectedFormDate.collection_amount;
                      const nextAct = fd.nextAction || selectedFormDate.branch_visit;
                      if (discTopics) fields.push({ label: 'Discussion Topics', value: discTopics });
                      if (nextAct) fields.push({ label: 'Next Action', value: nextAct });
                      break;
                    case 'New Account Opening':
                      const bizDetails = fd.businessDetails || selectedFormDate.collection_amount;
                      const credLimit = fd.creditLimit || selectedFormDate.branch_visit;
                      if (bizDetails) fields.push({ label: 'Business Details', value: bizDetails });
                      if (credLimit) fields.push({ label: 'Credit Limit', value: credLimit });
                      break;
                    case 'Complaint Resolution':
                      const compDetails = fd.complaintDetails || selectedFormDate.collection_amount;
                      const resSteps = fd.resolutionSteps || selectedFormDate.branch_visit;
                      const estTime = fd.estimatedResolutionTime;
                      if (compDetails) fields.push({ label: 'Complaint Details', value: compDetails });
                      if (resSteps) fields.push({ label: 'Resolution Steps', value: resSteps });
                      if (estTime) fields.push({ label: 'Estimated Resolution Time', value: estTime });
                      break;
                  }
                  const remarks = fd.remarks || selectedFormDate.next_due_date;
                  if (remarks) fields.push({ label: 'Remarks', value: remarks });
                } else {
                  if (selectedFormDate.next_due_date) fields.push({ label: 'Remarks', value: selectedFormDate.next_due_date });
                  if (selectedFormDate.branch_visit) fields.push({ label: 'Branch Visit', value: selectedFormDate.branch_visit });
                  if (selectedFormDate.collection_amount) fields.push({ label: 'Collection Amount', value: selectedFormDate.collection_amount });
                }

                // Group fields into pairs for 2-column layout
                const rows = [];
                for (let i = 0; i < fields.length; i += 2) {
                  rows.push(fields.slice(i, i + 2));
                }

                return (
                  <div className="p-2">
                    {rows.map((rowFields, ri) => (
                      <Row className="mb-2" key={ri}>
                        {rowFields.map((f, ci) => (
                          <Col md={6} key={ci} className="mb-2">
                            <div className="p-2.5 bg-light rounded border-bottom" style={{ minHeight: '62px' }}>
                              <small className="text-uppercase text-muted fw-bold d-block mb-1" style={{ fontSize: '10px', letterSpacing: '0.5px' }}>
                                {f.label}
                              </small>
                              <span className="text-dark font-size-14 fw-semibold">
                                {f.value || '—'}
                              </span>
                            </div>
                          </Col>
                        ))}
                      </Row>
                    ))}
                    {selectedFormDate.attachment && renderAttachment(selectedFormDate.attachment)}
                  </div>
                );
              })()
            ) : (
              (() => {
                const fields = [
                  { label: 'Staff', value: selectedFormDate.staffName },
                  { label: 'Date', value: moment(selectedFormDate.allowanceDate).format('DD-MMM-YYYY') },
                  { label: 'From', value: selectedFormDate.fromPlace },
                  { label: 'To', value: selectedFormDate.toPlace },
                  { label: 'Activity', value: selectedFormDate.activityName },
                  { label: 'Total KM', value: selectedFormDate.totalKm },
                  { label: 'Total Amount', value: selectedFormDate.totalAmount ? `₹${selectedFormDate.totalAmount}` : '₹0' },
                  { label: 'Bill No', value: selectedFormDate.billNo }
                ];
                if (selectedFormDate.dateOfPurchase) {
                  fields.push({ label: 'Date of Purchase', value: moment(selectedFormDate.dateOfPurchase).format('DD-MMM-YYYY') });
                  fields.push({ label: 'Dealer', value: selectedFormDate.nameOfDealer || 'N/A' });
                }

                // Group fields into pairs for 2-column layout
                const rows = [];
                for (let i = 0; i < fields.length; i += 2) {
                  rows.push(fields.slice(i, i + 2));
                }

                return (
                  <div className="p-2">
                    {rows.map((rowFields, ri) => (
                      <Row className="mb-2" key={ri}>
                        {rowFields.map((f, ci) => (
                          <Col md={6} key={ci} className="mb-2">
                            <div className="p-2.5 bg-light rounded border-bottom" style={{ minHeight: '62px' }}>
                              <small className="text-uppercase text-muted fw-bold d-block mb-1" style={{ fontSize: '10px', letterSpacing: '0.5px' }}>
                                {f.label}
                              </small>
                              <span className="text-dark font-size-14 fw-semibold">
                                {f.value || '—'}
                              </span>
                            </div>
                          </Col>
                        ))}
                      </Row>
                    ))}
                  </div>
                );
              })()
            )
          ) : (
            <p className="text-muted text-center py-3">No form data available.</p>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowFormModal(false)}>Close</Button>
        </Modal.Footer>
      </Modal>
    </React.Fragment>
  );
};

export default VisitorDetail;
